function findFirst(uint256[] calldata values, uint256 target) external pure returns (uint256) {
    for (uint256 i = 0; i < values.length; i++) {
        if (values[i] == target) return i;
    }
    return values.length;
}

pragma solidity ^0.8.20;
contract ControlLab {
    function sumUntil(uint256[] calldata values, uint256 limit) external pure returns (uint256 sum) {
        for (uint256 i = 0; i < values.length; i++) {
            sum += values[i];
            if (sum >= limit) break;
        }
    }
}
